using Moq;
using RedShirt.Api.Example.Connectors.Bar.Core.Models;
using RedShirt.Api.Example.Connectors.Bar.Core.Services;

namespace RedShirt.Api.Example.Connectors.Bar.Core.UnitTests.Tests.Services;

/// <summary>
///     Code generated by Cursor (Composer).
/// </summary>
public class IBarConnectorContractTests
{
    [Fact]
    public async Task IBarConnector_CanBeMockedForCreateAndGet()
    {
        var createResponse = new CreateBarConnectorResponse {Id = 1, Name = "alpha"};
        var getResponse = new GetBarConnectorResponse {Id = 1, Name = "alpha"};

        var connector = new Mock<IBarConnector>(MockBehavior.Strict);
        connector
            .Setup(c => c.CreateAsync(
                It.Is<CreateBarConnectorRequest>(r => r.Name == "alpha"),
                It.IsAny<CancellationToken>()))
            .ReturnsAsync(createResponse);
        connector
            .Setup(c => c.GetByIdAsync(1, It.IsAny<CancellationToken>()))
            .ReturnsAsync(getResponse);

        var created = await connector.Object.CreateAsync(
            new CreateBarConnectorRequest {Name = "alpha"},
            TestContext.Current.CancellationToken);
        var fetched = await connector.Object.GetByIdAsync(1, TestContext.Current.CancellationToken);

        Assert.Same(createResponse, created);
        Assert.Same(getResponse, fetched);
        connector.VerifyAll();
    }

    [Fact]
    public void IBarConnector_ExposesExpectedOperations()
    {
        var methods = typeof(IBarConnector)
            .GetMethods()
            .Select(m => m.Name)
            .OrderBy(n => n)
            .ToArray();

        Assert.Equal(["CreateAsync", "GetByIdAsync"], methods);
    }

    [Fact]
    public void RequestAndResponseModels_CanBeConstructed()
    {
        var createRequest = new CreateBarConnectorRequest {Name = "widget"};
        var createResponse = new CreateBarConnectorResponse {Id = 7, Name = "widget"};
        var getResponse = new GetBarConnectorResponse {Id = 7, Name = "widget"};

        Assert.Equal("widget", createRequest.Name);
        Assert.Equal(7, createResponse.Id);
        Assert.Equal("widget", createResponse.Name);
        Assert.Equal(7, getResponse.Id);
        Assert.Equal("widget", getResponse.Name);
    }
}